architecture.h4_f:
msg = CBOR{v:1, мәтін, жауап беру, жіберілген_ат}
ct = AES-GCM-256-шифрлау(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {шифр мәтіні: он алтылық(ct), жоқ: он алтылық}

cryptoWire.h1_f:
pt = CBOR{v:1, мәтін, жауап_беру?, тақырып_идентификаторы?, атап өту?, жіберілген_ат}
ct = AES-GCM-256-Шифрлау(бөлме_кілті, бір рет, pt, aad=он алтылық(бөлме_идентификаторы))
сым = CBOR{
  v: 1,
  шифрланған мәтін: hex(ct), // айнымалы ұзындық
  емес: он алтылық(12 B),
  sender_pseudo: он алтылық(16 B),
  жіберілген_ат: unix_ms
}

cryptoWire.h5_f:
сыртқы = CBOR{
  бастапқы_түйін: hex32,
  target_user: int64,
  ішкі_шифрмәтін: байт,
  inner_nonce: байт,
  жіберілген_ат: unix_ms
}
sig = Ed25519-Sign(source_priv, сыртқы)
POST /федерация/жеткізу { конверт: сыртқы, сиг: hex64 }

auth.h1_f:
POST /api/аутентификация/тіркеу
  { пайдаланушы аты, құпия сөз, x25519_public_key, дисплей_аты, телефон?, электрондық пошта?, avatar_emoji }

Жауап 201 Жасалған:
  { access_token, refresh_token, user_id, пайдаланушы аты, ...}

auth.h3_f:
access_token пайдалы жүктемесі:
  {қосалқы: пайдаланушы_идентификаторы, jti: құрылғы_идентификаторы, теру: "кіру", эксплуатация: қазір + 15 мин }
refresh_token пайдалы жүктемесі:
  {қосалқы: пайдаланушы_идентификаторы, jti: құрылғы_идентификаторы, теру: "жаңарту", экс: қазір + 30 күн }

HS256- .env жүйесінен түйіннің 64 байт құпиясымен қол қойылған

auth.h4_f:
register_begin(): шақыру = ранд(32)
                    опциялар = {rp.id, user.id, pubKeyCredParams, сынақ}
                    қайтару опциялары

тіркелу_аяқтау(аттестация):
  TPM / Secure Enclave түбірі CA бойынша аттестаттауды тексеру
  дүкен {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → {бірден: 128 биттік он алтылық, ttl: 60 }
QR пайдалы жүктеме = {бір рет емес, пайдаланушы_идентификаторы, сервер: "https://node.example" }

POST /api/authentication/qr/verify { бір рет емес }
  → тіркелген жаңа құрылғы; JWT қайтып оралды.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(бөлменің_псевдо_тұзы, жіберуші_идентификаторы)[:16] // 32 он алтылық
шифрлық мәтін = AES-GCM-шифрлау(бөлме_кілт, бір рет емес, CBOR_пайдалық жүктеме, aad=бөлме_идентификаторы)

Желдеткіш жақтау: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {файл аты, өлшемі, chunk_size_hint}
            ← {жүктеп салу_идентификаторы, бөлік_өлшемі}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct байт>
            ← 204
аяқтау POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL аяқталмаған: 24 сағ

files.h4_f:
жоққа шығару_тізімі = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
егер magic.from_buffer(buf[:1024]) бас тарту_тізімінде: қайтару 415

presence.h1_f:
клиент: бірінші пернені басу → жіберу {type:"t", state:"start"}
         күй өзгермейінше, 3 секундқа жіберілмейді
         Соңғы пернені басқаннан кейін 10 с → жіберу {type:"t", state:"stop"}
қабылдағыш: егер «тоқтату» келмесе, соңғы «іске қосудан» 10 с кейін автоматты тоқтату

calls.h1_f:
POST /api/calls/{room_id}/start {бейне, аудио} → call_id
WS трансляция {түрі:"c", түрі:"invite", call_id}
WS трансляция {түрі:"c", түрі:"ұсыныс", sdp}
WS трансляция {түрі:"c", түрі:"жауап", sdp}
WS хабар тарату {түрі:"c", түрі:"кандидат",мұз} × N
POST /api/calls/{call_id}/end

federation.h2_f:
конверт = {
  бастапқы_түйін: hex32,
  target_user: int64,
  ішкі_шифрмәтін: байт,
  inner_nonce: байт,
  жіберілген_ат: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(конверт))
POST /федерация/жеткізу { конверт, сиг }

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {атауы: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(қоғамдық_кілт_from_HTTPS_record)
DGA: домен(t) = базалық32( SHA256(тұқым ∥ YYYY-MM-DD) )[:16] + ".мысал"

push.h4_f:
iOS NSE: didReceive(сұрау) {шифрын шешу(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) {шифрын шешу(remoteMessage.data)}
Web SW: self.addEventListener('push', e => шифрын ашу(e.data))

controller.h2_f:
құрал = белгі_құралы
кіріс = бастапқы ағаш, keys/release.key
манифест = {
  нұсқасы: "0.1.0",
  құрастырылған: unix_ms,
  файлдар: [{жол, sha256, өлшем}, ...]
}
sig = Ed25519-Қол (release_priv, CBOR(манифест))
шығыс = INTEGRITY.sig.json = {манифест, қол қойған_: pub_hex, sig: sig_hex}

bots.h1_f:
жасау: POST /api/bots {пайдаланушы аты, дисплей_аты, код}
          → {bot_id, token, pubkey}
іске қосу: процесте (түйін ішіндегі корутин)
      OR сыртқы (ұзақ сауалнама /api/bots/{id}/updates, token-auth'd)
хабарлама: {мәтін, қолтаңба: Ed25519-Sign(bot_priv, canonical_msg)}

security.h4_f:
canary.txt (күнделікті):
  {күні, белгісі: Ed25519-Қол (шығару_priv, күні)}
клиент тексереді → жоқ немесе жарамсыз ⇒ компромисске күдіктенеді

төтенше жағдай:
  admin POST /api/admin/revoke-all {себеп}
  түйін таратылымдары {түрі:"n", оқиға:"компромисс", себебі}
  клиенттер кілттерді өшіреді, қайта жүктеуді мәжбүрлейді

debugging.h2_f:
гистограммаларды бағалау (бағыт + әдіс бойынша):
  vortex_http_requests_total{бағыт,әдіс,күй}
  vortex_http_request_duration_seconds_bucket{бағыт,метод,le}

веб-розеткалар:
  vortex_ws_connections{түйін}
  vortex_ws_fanout_queue_depth{бөлме,пайдаланушы}

теңшелетін есептегіштер:
  vortex_messages_sent_total{бөлменің_түрі}
  құйынды_қоңыраулар_басталды_жалпы{түрі}

login.h4_f:
сәтті: 201 + JWT конверт (тізіліммен бірдей пішін)
2FA бойынша қажет: 200 { "needs_2fa": шын } (әзірше JWT жоқ)
сәтсіздікте: 401 { "қате":"жарамсыз_тіркеу деректері"}

apns.h1_f:
POST https://api.push.apple.com/3/device/<device_token>
Тақырыптар: apns-тақырып: <bundle_id>, apns-push-type: alert, apns-collapse-id: бөлме:42
Негізгі мәтін: {апс: {ескерту: {атауы, негізгі бөлігі}}, деректер: <мұқабаланған>}

bmp.h1_f:
пошта жәшігі_идентификаторы = HKDF(алушы_pubkey, info="bmp-v1", len=32)
Депозит: POST /bmp/deposit {mailbox_id, blob ≤1MB}
Алып алу: GET /bmp/messages (аудандылығы расталған)

controller.h1_f:
GET /v1/integrity → {күй, қол қойған_, сәйкестендірілген, сәйкес емес, …}
GET /v1/health → {күй, нұсқа, пабки, статистика}
GET /v1/entries → [{протокол, url}, …]
GET /v1/mirrors → [controller_url, …]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Авторизация: Тасымалдаушы <oauth2_token>
Негізгі мәтін: {хабарлама: {таңбалауыш: <құрылғы>, деректер: {...мөрленген...}, Android: {collapse_key}}}

federation.h1_f:
конверт = {көзі_түйін, мақсатты_пайдаланушы, ішкі_кт, ішкі_нақты, жіберілген_ат}
sig = Ed25519-Sign(source_priv, CBOR(конверт))
POST /федерация/жеткізу {конверт, сиг}
B тексереді: федерацияларға қарсы сиг [source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE хабарлар_фут USING фут5(
  мазмұн, -- таңбаланған баған
  бөлме идентификаторы UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
сұрау: SELECT rowid FROM messages_fts WHERE мазмұн MATCH 'foo'

gravitix.h1_f:
on /start { emit "Қош келдіңіз, {ctx.first_name}" }
/қосу <элемент> {
  state.list = (state.list немесе []) + [ctx.args.item]
  шығару "Қосылды: {ctx.args.item}"
}

prekey.h1_f:
бума = {
  сәйкестік_пк,
  signed_prekey_pk,
  signed_prekey_sig = Ed25519-Sign(identity_priv, signed_prekey_pk),
  бір реттік_алдын ала кілттер: [pk_0, pk_1, ..., pk_9]
}

vapid.h1_f:
VAPID пернелері: әр түйін үшін Ed25519 пернелер жұбы
JWT белгісі: {ауд: push_service_origin, мерзімі: қазір + 12 сағ, қосымша: mailto:ops@example}
push сұрау тақырыптары: Авторизация: vapid t=<jwt>, k=<vapid_public_key>
